local config = {
  ui_story_30420401_1_dialog_content = "...",
  ui_story_30420401_2_dialog_content = "......!",
  ui_story_30420401_3_dialog_content = "Pak, jangan mendekat. Ironjaw-mu agak menyeramkan jika dilihat dari dekat.",
  ui_story_30420401_4_dialog_content = "Jadi... apa yang terjadi?",
  ui_story_30420401_5_dialog_content = "Aku dipanggil Illumina untuk mengikuti suatu pertemuan. Kamu tahu apa yang kami bicarakan saat pertemuan itu?",
  ui_story_30420401_6_option_content = "Tidak. Apa yang kalian bicarakan?",
  ui_story_30420401_7_dialog_content = "Seharusnya aku tidak memberitahumu. Namun, situasi kali ini istimewa, jadi aku harus memikirkannya.",
  ui_story_30420401_8_option_content = "Sebenarnya... aku tidak mau tahu.",
  ui_story_30420401_9_dialog_content = "Kamu harus tahu meski tidak mau tahu, tetapi aku berpikir apakah aku harus memberitahumu.",
  ui_story_30420401_10_option_content = "???",
  ui_story_30420401_11_dialog_content = [[
Seharusnya aku mengambilkanmu cermin agar kamu berkaca betapa polosnya kamu saat ini.
Sesuatu yang buruk mungkin terjadi padamu besok jika kutinggalkan kamu sendiri.]],
  ui_story_30420401_12_option_content = "...",
  ui_story_30420401_13_dialog_content = "Jangan diam saja! Teruslah bertanya! Ini soal kamu, bertanyalah kepadaku apa yang terjadi!",
  ui_story_30420401_14_dialog_content = "Yang terjadi sebenarnya adalah... saat pertemuan bersama Legion Commander Illumina...",
  ui_story_30420401_15_dialog_content = "Kita mendapat perintah dari Grand Marshal, yaitu: \"Menarik. Awasi orang itu dengan ketat.\"",
  ui_story_30420401_16_dialog_content = "Apakah kita seharusnya mewujudkan perintah itu menjadi rencana? Lady Chief kita takkan senang dengan itu.",
  ui_story_30420401_17_dialog_content = "Jangan khawatir, ini keahlian Vivian.",
  ui_story_30420401_18_dialog_content = "Jadi, bagaimana kita akan mengawasinya? Usulku, sikat dan kunci dia di suatu tempat. Kalian punya ide?",
  ui_story_30420401_19_dialog_content = "Tenanglah, salah satu di antara kita akan berhubungan dengannya.",
  ui_story_30420401_20_dialog_content = "Singkatnya, sebelum usulan yang terperinci siap, kita hanya perlu mengawasi orang itu.",
  ui_story_30420401_21_dialog_content = "Tunggu, memangnya siapa orang yang harus diperhatikan ini? Jangan bilang hanya aku yang tidak tahu. Kalian juga tampaknya tidak banyak tahu.",
  ui_story_30420401_22_dialog_content = "Dalam hal pertarungan, jelas dia lemah. Dia punya bakat istimewa, tetapi Legion Commander tidak layak terlibat dengannya.",
  ui_story_30420401_23_dialog_content = "Selain Colossus itu, katakan mengapa PlayerName sangat berharga bagi Illumina.",
  ui_story_30420401_24_dialog_content = "<color=#FFB400>Tubuh</color>.",
  ui_story_30420401_25_dialog_content = "<color=#FFB400>Garis keturunan</color>.",
  ui_story_30420401_26_dialog_content = "<color=#FFB400>Otak</color>... Atau lebih tepatnya, kemampuan psikis.",
  ui_story_30420401_27_dialog_content = "...",
  ui_story_30420401_28_dialog_content = "Apa pun itu, aku rasa inilah masalah yang harus didiskusikan lebih lanjut! Sebelum rencana lebih detailnya siap, jangan ada yang menyentuh PlayerName!",
  ui_story_30420401_X28_dialog_content = "Itulah yang terjadi.",
  ui_story_30420401_29_option_content = "Apakah aku baru saja mendapatkan berita luar biasa?",
  ui_story_30420401_30_dialog_content = "Memangnya, untuk apa aku memintamu datang kemari? Masa hanya untuk mengobrol?",
  ui_story_30420401_31_option_content = "Sungguh kisah yang mengharukan, penuh liku tanpa akhir.",
  ui_story_30420401_32_dialog_content = "Waktu kita tidak banyak. Aku hanya memberitahumu hal yang aku rasa paling penting.",
  ui_story_30420401_33_dialog_content = "Di sisi lain, ada yang menyebutmu lemah saat pertemuan itu. Bagaimana perasaanmu tentang itu?",
  ui_story_30420401_34_option_content = "Bukankah kamu yang bilang begitu? Aku memang lemah.",
  ui_story_30420401_35_dialog_content = "Ya, tetapi itu karena aku khawatir tiga Legion Commander lainnya akan menaruh perhatian khusus padamu. Paham?",
  ui_story_30420401_36_option_content = "Aku tidak jago bertarung, tetapi aku punya keahlian lain!",
  ui_story_30420401_37_dialog_content = "Terkadang kurangnya daya bertarung menentukan segalanya. Mungkin sudah terlambat ketika kamu menyadarinya!",
  ui_story_30420401_38_dialog_content = "Diamlah, jangan bergoyang!",
  ui_story_30420401_39_dialog_content = "Lihat badanmu yang kecil. Sekarang apa kau sadar betapa ruginya jika tidak ikut bertempur?",
  ui_story_30420401_40_dialog_content = "Sebenarnya aku tahu perasaanmu. Jangan kira aku selalu sekuat ini. Dulu aku hanya orang biasa.",
  ui_story_30420401_41_dialog_content = "Kamu paham kenapa aku memberitahumu semua ini sekarang?",
  ui_story_30420401_42_option_content = "Sepertinya paham. Mungkin.",
  ui_story_30420401_43_dialog_content = "Sepertinya kamu tidak tahu alasanku melakukan ini. Kelihatan dari raut wajahmu.",
  ui_story_30420401_44_option_content = "Tunggu, aku tidak paham perkataanmu.",
  ui_story_30420401_45_dialog_content = "Tentu saja aku ingin melihat reaksimu! Kamu pikir aku suka melatih orang seperti orang itu?",
  ui_story_30420401_46_dialog_content = "Apa pun yang terjadi nanti, jika kamu bergabung dengan Illumina atas alasan apa pun, ingatlah untuk tetap berada di pihakku. Paham?",
  ui_story_30420401_47_option_content = "Tidak usah, lagi pula aku tidak berminat...",
  ui_story_30420401_48_dialog_content = "Saat ini mungkin kamu berpikiran begitu, tapi entah jika waktunya tiba. Kamu tahu betapa sombongnya Illumina General kita?",
  ui_story_30420401_49_option_content = "Entahlah, tetapi aku akan melakukannya.",
  ui_story_30420401_50_dialog_content = "Benar! Jangan lupa mereka rela berbuat apa saja demi Power Puzzle.",
  ui_story_30420401_51_dialog_content = "Dengar, jika kamu terpisah dariku, mereka akan <color=#FFB400>memakanmu hidup-hidup</color>!",
  ui_story_30420401_52_dialog_content = "Nyawamu setidaknya tidak akan terancam di bawah perlindunganku.",
  ui_story_30420401_53_dialog_content = "Meski aku akan menjalankan rencana Illumina, aku adalah orang biasa yang menggunakan cara normal meski aku sangat suka bertarung!",
  ui_story_30420401_54_dialog_content = "Tepat! Siapa pun yang bertanya, jawabanmu selalu adalah—",
  ui_story_30420401_55_dialog_content = "<size=45>\"Aku memilih cara Barton, jadi aku bersama Barton\"!</size>",
  ui_story_30420401_56_dialog_content = "Kamu paham?",
  ui_story_30420101_1_dialog_content = "Omong-omong, apa artinya bertarung bagi Barton?",
  ui_story_30420101_2_dialog_content = "Kamu petarung berbakat, tidak seperti aku.",
  ui_story_30420101_3_dialog_content = "Yang bisa aku lakukan hanyalah menggunakan tubuhku yang renta untuk <color=#FFB400>membuka jalan</color> bagimu.",
  ui_story_30420101_4_dialog_content = "Manfaatkan aku untuk melangkah maju...",
  ui_story_30420101_5_dialog_content = "Ini juga arti penting dari perang ini.",
  ui_story_30420101_X5_dialog_content = "Apa?",
  ui_story_30420101_X6_dialog_content = "Tidak ada apa-apa, hanya bicara pada diri sendiri.",
  ui_story_30420101_6_dialog_content = "Kalau dipikir-pikir... Duduklah dan bermain catur bersamaku.",
  ui_story_30420101_7_dialog_content = "Jangan terlalu tenggang hati. Aku akan menjadi Hitam, dan kamu jadi Putih!",
  ui_story_30420101_X7_dialog_content = "Namun, aku tidak melihat ada Alchemy Board!?",
  ui_story_30420101_X8_dialog_content = "Pola pikir, kemampuan memahami, dan imajinasi. Gunakan kecerdasanmu dengan benar. Perang telah dimulai.",
  ui_story_30420101_8_option_content = "Tunggu, aku tidak paham.",
  ui_story_30420101_9_dialog_content = "Oh? Kamu akan sia-siakan langkah ini? Kalau begitu, kuserang kamu dengan pionku.",
  ui_story_30420101_10_option_content = "Pion melangkah dua petak!",
  ui_story_30420101_11_dialog_content = "Pion menyerang!",
  ui_story_30420101_12_dialog_content = "Barisan depanmu telah dikalahkan. Apa yang akan kamu lakukan?",
  ui_story_30420101_13_dialog_content = "Tunggu, bukankah itu melanggar aturan? Ada yang aneh.",
  ui_story_30420101_14_dialog_content = "Inikah caramu bermain catur?",
  ui_story_30420101_15_dialog_content = "Hentikan. Apa langkahmu selanjutnya?",
  ui_story_30420101_16_option_content = "Bisa kita mulai lagi? Aku belum siap.",
  ui_story_30420101_17_dialog_content = "Tidak bisa. Pion akan menyerang bagian tengah Putih. Jenderal tidak akan bergerak.",
  ui_story_30420101_18_option_content = "Serang dengan pion yang tersisa?",
  ui_story_30420101_19_dialog_content = "Pion! Serang sayap samping Putih!",
  ui_story_30420101_20_option_content = "Lindungi bagian tengah dengan menteri?",
  ui_story_30420101_21_dialog_content = "Putih memimpin dengan Colossus, mengorbankan pion!",
  ui_story_30420101_22_option_content = "Buat pion berjaga-jaga?",
  ui_story_30420101_23_dialog_content = "Barisan depan tertahan. Perluas inisiatif!",
  ui_story_30420101_24_option_content = "Serang dengan benteng? Apa aku punya benteng?",
  ui_story_30420101_25_dialog_content = "Bukankah kamu punya Colossus? Gunakan sebagai menteri atau benteng dan gunakan dengan baik.",
  ui_story_30420101_26_option_content = "Tunggu, apa lagi yang bisa aku gunakan?",
  ui_story_30420101_27_dialog_content = "Bukankah kamu masih punya banyak pion? Mereka tampak kuat dan mampu berjaga.",
  ui_story_30420101_28_dialog_content = "Pionku akan menghampiri rajamu di babak berikutnya. Kamu akan kalah jika terus berdiam diri!",
  ui_story_30420101_29_dialog_content = "Aku paham sekarang! Permainan ini hanya omong kosong, kalau begitu, akan kugunakan apa pun!",
  ui_story_30420101_30_dialog_content = "Rajaku akan kabur, membiarkan pion menyerang jenderal Hitam!",
  ui_story_30420101_31_dialog_content = "Jenderal Hitam telah dikalahkan, selamat!",
  ui_story_30420101_32_option_content = "Itu artinya aku menang? Haruskah aku merayakan?",
  ui_story_30420101_33_dialog_content = "Mungkin kamu raja tanpa daya bertarung, tetapi pendampingmu bersedia bertarung untukmu, meskipun kalah jumlah.",
  ui_story_30420101_34_option_content = "Eh? Kenapa? Apa yang terjadi?",
  ui_story_30420101_35_dialog_content = "Kamu terlahir dengan mata yang tajam. Dengan Colossus sebagai perisaimu, kamu bisa menilai situasi sementara Hitam tidak bisa.",
  ui_story_30420101_36_dialog_content = "Namun... menurutmu ini sudah berakhir?",
  ui_story_30420101_37_dialog_content = "Pion — Hiiro ke baris akhir. Promosi!",
  ui_story_30420101_38_dialog_content = "Pion — Sharona ke baris akhir. Promosi!",
  ui_story_30420101_39_dialog_content = "Pion — Barton ke jajaran terakhir. Promosi! Para jenderal bertarung bersama dan menangkap raja Putih!",
  ui_story_30420101_40_dialog_content = "Kita menang. Kamu tahu alasannya?",
  ui_story_30420101_41_dialog_content = "Tunggu?! Apa yang terjadi?",
  ui_story_30420101_42_dialog_content = "Mudah saja.",
  ui_story_30420101_43_dialog_content = "Meski kamu mengalahkan jenderal Hitam, pion Hitam dipromosikan menjadi karakter yang luar biasa dan mengalahkanmu.",
  ui_story_30420101_44_dialog_content = "Sepertinya itu karena rajamu tidak muncul.",
  ui_story_30420101_45_dialog_content = "Tidak, kita bisa menukar raja selama pertandingan. Kamu bisa bertanya pada Grand Marshal soal ini.",
  ui_story_30420101_46_dialog_content = "Biar kujelaskan!",
  ui_story_30420101_47_dialog_content = "Alasan kita menang adalah karena <color=#FFB400>para jenderal membuka jalan untuk kita</color>.",
  ui_story_30420101_48_dialog_content = "Jadi, pion petarung kita mengumpulkan cukup kekuatan untuk berubah demi mengamankan kemenangan!",
  ui_story_30420101_49_dialog_content = "Sementara untuk cerita aneh yang kamu dengar sebelum simulasi, itu hanyalah cerita tentang perwira lamaku, Pango.",
  ui_story_30420101_50_dialog_content = "Saat menghadapi lawan yang kuat, tujuan dari pertumpahan darah bagi kita adalah:",
  ui_story_30420101_51_dialog_content = "<size=45>Untuk membuka jalan menuju kemenangan!</size>",
  ui_story_30420601_1_dialog_content = "\"Tiada akhir dan tak terduga; terkadang tenang, terkadang bergejolak.\"",
  ui_story_30420601_2_dialog_content = "Laut.",
  ui_story_30420601_3_dialog_content = "Menaklukkan, atau ditaklukkan.",
  ui_story_30420601_4_dialog_content = "Guk!",
  ui_story_30420601_5_dialog_content = "Hmm? Dari mana anak-anak anjing itu berasal?",
  ui_story_30420601_6_dialog_content = "Mereka bukan anak anjing! Mereka adalah <color=#FFB400>serigala putih</color> yang kulatih dan kubesarkan.",
  ui_story_30420601_7_dialog_content = "Oh? Aku tidak tahu kamu punya piaraan yang imut, Commander Barton!",
  ui_story_30420601_8_dialog_content = "Baiklah, cukup... Aku datang untuk bertanya, apakah Grand Marshal telah menanggapi permintaanku sebelumnya?",
  ui_story_30420601_9_dialog_content = "Maksudmu, permintaanmu untuk <color=#FFB400>mendirikan angkatan laut</color>?",
  ui_story_30420601_10_dialog_content = "Ya. Baru-baru ini aku membaca sebuah buku yang berisi pengetahuan yang luas tentang keunggulan angkatan laut.",
  ui_story_30420601_11_dialog_content = "Aku segera menyadari pasukan Illumina terbatas pada pertempuran darat. Bagiku, ini penerapan kekuatan kita yang terlalu terpusat.",
  ui_story_30420601_12_dialog_content = "Untuk memperluas kekuatan, pertama-tama, kita harus memperluas ke laut lepas!",
  ui_story_30420601_13_dialog_content = "Satu-satunya kekurangan Illumina hingga saat ini adalah armada laut yang layak!",
  ui_story_30420601_14_dialog_content = "Kemudian, ini akan menjadi kejutan yang menyenangkan. Aku baru saja mau memberitahumu bahwa Grand Marshal menyukai saranmu.",
  ui_story_30420601_15_dialog_content = "Beliau telah memberikan perintah untuk menempatkanmu di komando angkatan laut, serta memberikan tanggung jawab penuh atas pendiriannya kepadamu.",
  ui_story_30420601_16_dialog_content = "Keputusan Grand Marshal sungguh bijaksana. Aku bersumpah aku tidak akan mengecewakan siapa pun. Kita akan memiliki angkatan laut paling kuat yang pernah ada di dunia!",
  ui_story_30420601_17_dialog_content = "Meski Illumina hanya memiliki satu kapal... Kuharap kamu akan memanfaatkannya dengan baik?",
  ui_story_30420601_18_dialog_content = "Hahahaha! Itu lebih dari cukup!",
  ui_story_30420601_19_dialog_content = "Laut tidak lebih dari genangan air besar yang ada di darat.",
  ui_story_30420601_20_dialog_content = "Dengan kepemimpinanku, samudra akan menjadi milik Illumina dalam waktu singkat!",
  ui_story_30420601_21_dialog_content = "Kalau begitu, kami akan menunggu kabar baik darimu, Commander Barton.",
  ui_story_30420601_22_dialog_content = "Guk!",
  ui_story_30420601_23_dialog_content = "Jadi, inilah laut...",
  ui_story_30420601_24_dialog_content = "Kita benar-benar akan pergi ke laut, Commander...?",
  ui_story_30420601_25_dialog_content = "Apa maksudmu? Maksudmu pria dan wanita pemberani dari angkatan laut besar Illumina takut pada laut?!",
  ui_story_30420601_26_dialog_content = "Kalian semua, camkan! Kalian adalah prajurit Illumina yang bangga, singkirkanlah setiap jiwa-jiwa pengecutmu dalam diri! Paham?",
  ui_story_30420601_27_dialog_content = "Ikuti perintahku, naik ke kapal dan angkat sauh!",
  ui_story_30420601_28_dialog_content = "Siap, Pak!",
  ui_story_30420601_29_dialog_content = "Mereka bilang para pelaut itu biasanya membuat jurnal perjalanan, jadi biarkan ini menjadi catatan Conquest of the Sea milikku!",
  ui_story_30420601_30_dialog_content = "Hari ini, kami secara resmi memulai perjalanan. Tepat sebelum berlayar, seorang prajurit bertanya kepadaku apakah kami benar-benar akan melaut.",
  ui_story_30420601_31_dialog_content = "Apakah dia juga menyadarinya? Untuk sesaat, bukan, kurang dari sedetik... Bahkan aku mungkin gemetar memikirkannya...",
  ui_story_30420601_32_dialog_content = "Menatap samudra dengan mata kepala sendiri untuk kali pertama... Sedikit berbeda dari yang kubayangkan.",
  ui_story_30420601_33_dialog_content = "Dalam tak terduga dan membentang menuju cakrawala tanpa batas... Rasanya laut yang membentang ini membuatku ciut...",
  ui_story_30420601_34_dialog_content = "Namun, ini takkan pernah bisa menghentikanku. Tidak peduli seberapa pun luasnya, setiap tetesnya akan berada di bawah kendaliku!",
  ui_story_30420601_35_dialog_content = "<color=#e8d9bb>Wuuss... Ciprat, ciprat... Wuuss...</color>",
  ui_story_30420601_36_dialog_content = "Argh...",
  ui_story_30420601_37_dialog_content = "Commander... Kurasa kecepatan seperti ini akan memperburuk mabuk lautmu...",
  ui_story_30420601_38_dialog_content = "Jangan khawatir... Katakan apa yang terjadi di sini?!",
  ui_story_30420601_39_dialog_content = "Siap, Pak! Air tiba-tiba masuk ke lambung kapal, Commander. Situasinya mengerikan!",
  ui_story_30420601_40_dialog_content = "Ah, sial. Di saat seperti ini... Bagaimana progres perbaikannya?",
  ui_story_30420601_41_dialog_content = "Semua awak bekerja tanpa henti untuk memperbaiki lambung kapal, Pak. Namun...",
  ui_story_30420601_42_dialog_content = "Cepat katakan, prajurit! Jangan buang-buang waktu!",
  ui_story_30420601_43_dialog_content = "Badai telah menghambat kemajuan kita. Jika begini terus, hanya masalah waktu sebelum seluruh kapal tenggelam...",
  ui_story_30420601_44_dialog_content = "Sulit dipercaya...",
  ui_story_30420601_45_dialog_content = "Y-yakinlah, Commander! Tak satu pun dari kami berniat untuk meninggalkan kapal! Kami bersamamu hingga akhir!",
  ui_story_30420601_46_dialog_content = "Tidak, yang kumaksud adalah...",
  ui_story_30420601_47_dialog_content = "Bahwa ekspedisi pertama kita ke laut harus berakhir seperti ini... Sulit dipercaya! Sungguh tidak masuk akal!",
  ui_story_30420601_48_dialog_content = "Namun, jika terus memperjuangkan kemenangan, kita tidak punya pilihan... Selain evakuasi!",
  ui_story_30420601_49_dialog_content = "Dengar, para prajurit! Naik ke sekoci, dan evakuasi dari kapal!",
  ui_story_30420601_50_dialog_content = "Siap, Pak!",
  ui_story_30420601_51_dialog_content = "Argh...",
  ui_story_30420601_52_dialog_content = "Ini sekoci terakhir, Commander. Naiklah.",
  ui_story_30420601_53_dialog_content = "Hah? Hanya ada satu tempat tersisa...?",
  ui_story_30420601_54_dialog_content = "Bagaimana denganmu, prajurit?",
  ui_story_30420601_55_dialog_content = "Aku tetap di kapal, Pak!",
  ui_story_30420601_56_dialog_content = "Bukan kamu yang memutuskan!",
  ui_story_30420601_57_dialog_content = "Tapi, Pak...",
  ui_story_30420601_58_dialog_content = "Diam, prajurit! Kamu harus kembali melapor kepada Grand Marshal, dan katakan kepadanya... Katakan kepadanya bahwa ekspedisi laut pertama kita gagal!",
  ui_story_30420601_59_dialog_content = "S-siap, Pak!",
  ui_story_30420601_60_dialog_content = "Auuuh!",
  ui_story_30420601_61_dialog_content = "Sial... Aku tidak percaya aku melupakan kalian berdua...",
  ui_story_30420601_62_dialog_content = "Kapal ini... Dan kita bersamanya... Sebentar lagi akan tenggelam...",
  ui_story_30420601_63_dialog_content = "Ambillah, pegang papan kayu ini... Jangan lepaskan, apa pun yang terjadi...",
  ui_story_30420601_64_dialog_content = "Mendengking...",
  ui_story_30420601_65_dialog_content = "Kami berlayar menuju badai beberapa hari yang lalu. Kapal kemasukan air, dan tidak lama kemudian... Seluruh kapal tenggelam ke dasar laut.",
  ui_story_30420601_66_dialog_content = "Aku memerintahkan setiap awak untuk melarikan diri dengan sekoci. Aku hanya bisa berharap mereka berhasil sampai ke pantai dalam keadaan aman dan selamat...",
  ui_story_30420601_67_dialog_content = "Jika ada dua kata yang tidak bisa kutahan, itu adalah \"melarikan diri\"... Namun, hari itu, aku tidak punya pilihan selain menyerah dan melarikan diri demi hidup kami.",
  ui_story_30420601_68_dialog_content = "Menyerah... Sebuah kata yang sama sekali tidak pernah terlintas dalam benakku.",
  ui_story_30420601_69_dialog_content = "Namun, pada akhirnya, kami gagal menaklukkan lautan. Sebaliknya, laut menenggelamkan kami...",
  ui_story_30420601_70_dialog_content = "Guk guk!",
  ui_story_30420601_71_dialog_content = "Hvit... Ulv... Kita aman untuk saat ini...",
  ui_story_30420601_72_dialog_content = "Ini mungkin pulau tak berpenghuni tanpa sarana perjalanan atau komunikasi...",
  ui_story_30420601_73_dialog_content = "Namun, setidaknya ada banyak sumber daya bagi kita untuk bertahan hidup lebih lama.",
  ui_story_30420601_74_dialog_content = "Arf!",
  ui_story_30420601_75_dialog_content = "Laut... Tak pernah kubayangkan tempat ini begitu berbahaya ataupun kejam...",
  ui_story_30420601_76_dialog_content = "Itu mengingatkanku...",
  ui_story_30420601_77_dialog_content = "Pada seekor Eclipsite raksasa, dengan rahang dalam yang bisa melahap apa saja dan semua yang terlihat...",
  ui_story_30420601_78_dialog_content = "Tidak... Laut jauh lebih menakutkan daripada Eclipsite mana pun...",
  ui_story_30420601_79_dialog_content = "Jauh lebih menakutkan...",
  ui_story_30420601_80_dialog_content = "Guk! Guk!",
  ui_story_30420601_81_dialog_content = "Hvit, Ulv... Aku terlalu naif saat kali pertama kita berangkat menjelajahi laut.",
  ui_story_30420601_82_dialog_content = "Aku tidak bisa mendirikan angkatan laut atas nama Illumina... Aku bahkan tidak bisa mencegah satu-satunya kapal kita agar tidak tenggelam...",
  ui_story_30420601_83_dialog_content = "Aku gagal menepati janjiku. Commander–atau dalam hal ini, tentara–macam apa aku ini?",
  ui_story_30420601_84_dialog_content = "Guk! Guk!",
  ui_story_30420601_85_dialog_content = "Kamu mau berlatih sekarang, di saat seperti ini? Lupakan, pergilah bermain...",
  ui_story_30420601_86_dialog_content = "Guk...!",
  ui_story_30420601_87_dialog_content = "Berhenti menarikku! Aku perlu menyendiri untuk sementara waktu...",
  ui_story_30420601_88_dialog_content = "Grr...",
  ui_story_30420601_89_dialog_content = "Hmm? Sedang apa kalian berdua dengan potongan kayu itu?",
  ui_story_30420601_90_dialog_content = "Hati-hati! Jangan sampai masuk ke air!",
  ui_story_30420601_91_dialog_content = "Guk!",
  ui_story_30420601_92_dialog_content = "Hah... Apakah Hvit dan Ulv... berselancar?!",
  ui_story_30420601_93_dialog_content = "Kapan mereka berdua belajar melakukannya?",
  ui_story_30420601_94_dialog_content = "Dan kelihatannya... Mereka juga tampak bahagia?",
  ui_story_30420601_95_dialog_content = "Guk! Guk!",
  ui_story_30420601_96_dialog_content = "Tidak, aku tak bisa berselancar. Kalian berdua bersenang-senanglah.",
  ui_story_30420601_97_dialog_content = "Guk! Guk! Guk!",
  ui_story_30420601_98_dialog_content = "Baiklah. Aku akan mencobanya...",
  ui_story_30420601_99_dialog_content = "Guk...!",
  ui_story_30420601_100_dialog_content = "Pertama-tama, naiki papan, beberapa kayuhan, lalu tunggu ombaknya...",
  ui_story_30420601_X100_dialog_content = "Ah! Uhuk, uhuk... Airnya...",
  ui_story_30420601_101_dialog_content = "Kurang baik! Aku harus mencoba lagi!",
  ui_story_30420601_102_dialog_content = "Tunggu ombaknya, lalu berdiri...",
  ui_story_30420601_103_dialog_content = "Hei! Berhasil! Aku berhasil!!",
  ui_story_30420601_X103_dialog_content = "Ah...!",
  ui_story_30420601_X104_dialog_content = "Uhuk, uhuk... jatuh lagi...",
  ui_story_30420601_104_dialog_content = "Guk!",
  ui_story_30420601_105_dialog_content = "Hahaha! Kalian berdua Jangan menertawakanku! Kalian juga tidak selalu berhasil!",
  ui_story_30420601_106_dialog_content = "Hmm? Apakah aku... merasa bahagia juga?",
  ui_story_30420601_107_dialog_content = "Auuuuh!",
  ui_story_30420601_108_dialog_content = "Jadi, laut bisa menjadi sumber kebahagiaan, sekaligus ketakutan...",
  ui_story_30420601_109_dialog_content = "Yang dibutuhkan hanyalah sedikit latihan, dan aku bisa merasakan kesenangan berselancar.",
  ui_story_30420601_110_dialog_content = "Dengan cara yang tepat, serta banyak latihan...",
  ui_story_30420601_111_dialog_content = "Jika aku bisa menaklukkan ombak laut... Mungkin aku masih bisa menaklukkan seluruh lautan kelak!",
  ui_story_30420601_112_dialog_content = "Hvit! Ulv! Terima kasih banyak!",
  ui_story_30420601_113_dialog_content = "Aku tidak boleh membuang-buang waktu lagi berkubang dalam kegagalanku!",
  ui_story_30420601_114_dialog_content = "Guk!",
  ui_story_30420601_115_dialog_content = "Insiden ini menjadi pengungkap kelemahan dan kekurangan angkatan laut kita.",
  ui_story_30420601_116_dialog_content = "Jika badai kecil saja sudah cukup untuk mengalahkan kita, tidak bisa kubayangkan apa yang akan terjadi jika kita menghadapi musuh.",
  ui_story_30420601_117_dialog_content = "Kegagalan kita adalah kurangnya pemahaman tentang laut dan strategi yang tepat untuk menaklukkannya.",
  ui_story_30420601_118_dialog_content = "Karena itulah, mulai hari ini, kita harus lebih banyak latihan fisik dan jadwal latihan khusus angkatan laut!",
  ui_story_30420601_119_dialog_content = "Meski tidak bisa membangun angkatan laut yang berjaya di generasi kita, seharusnya itu tidak menjadi alasan bagi kita untuk menyerah!",
  ui_story_30420601_120_dialog_content = "Kita perlu menganalisis pengalaman dan kesulitan lalu meringkasnya dalam sebuah buku pedoman...",
  ui_story_30420601_121_dialog_content = "Jadi, kelak pengalaman ini akan menjadi fondasi angkatan laut Illumina yang tak terkalahkan!",
  ui_story_30420601_122_dialog_content = "Guk!!!",
  ui_story_30420601_123_dialog_content = "Ayo, Hvit! Ulv! Pelatihan kita dimulai sekarang!",
  ui_story_30420601_124_dialog_content = "Arf?",
  ui_story_30420601_125_dialog_content = "Anggap diri kalian sebagai prajurit yang bangga di angkatan laut besar kita!",
  ui_story_30420601_126_dialog_content = "Guk!",
  ui_story_30420601_127_dialog_content = "Hari pertama pelatihan di pulau tak berpenghuni kita! Latihan pemanasan!",
  ui_story_30420601_128_dialog_content = "Guk!!",
  ui_story_30420601_129_dialog_content = "Dengan tekad dan keberanian, kita taklukkan lautan!",
  ui_story_30420601_130_dialog_content = "Guk!!!",
  ui_story_30420601_131_dialog_content = "Dimulai dengan berlari 20 kilometer...",
  ui_story_30420601_X131_dialog_content = "Siap... Mulai!",
  ui_story_30420601_132_dialog_content = "Guk!",
  ui_story_30420601_133_dialog_content = "Sial, mereka berdua cepat! Namun, aku tidak boleh tertinggal...!",
  ui_story_30420601_135_dialog_content = "Ikuti aba-abaku!",
  ui_story_30420601_136_dialog_content = "Kiri! Kiri! Kiri, kanan, kiri! Hup, dua, tiga, empat!",
  ui_story_30420601_137_dialog_content = "Guk!",
  ui_story_30420601_138_dialog_content = "Lebih cepat! Hup, dua, tiga, empat!",
  ui_story_30420601_139_dialog_content = "Arf, arf, arf, arf!",
  ui_story_30420601_140_dialog_content = "Itu baru semangat! Kiri! Kiri! Kiri, kanan, kiri!",
  ui_story_30420601_141_dialog_content = "...Entri jurnal dari beberapa hari terakhir ditulis oleh seseorang yang benar-benar berbeda.",
  ui_story_30420601_142_dialog_content = "Aku tidak akan gentar lagi dalam menghadapi tantangan, dan aku menolak untuk menyerah lagi!",
  ui_story_30420601_143_dialog_content = "Jika aku berdiam saja, laut akan menaklukkanku suatu hari nanti...",
  ui_story_30420601_144_dialog_content = "Namun, jika aku terus berjuang, jika aku tetap aktif, suatu hari nanti... masih ada kesempatan bagiku!",
  ui_story_30420601_145_dialog_content = "Tidak ada kata terlambat...",
  ui_story_30420601_146_dialog_content = "Hari ini adalah hari ke-50 pelatihan kita di pulau ini, dan aku harus membuat pengumuman!",
  ui_story_30420601_147_dialog_content = "Pengumumannya adalah, bahwa dua prajurit kita, Hvit dan Ulv, meraih hasil yang gemilang selama pelatihan mereka!",
  ui_story_30420601_148_dialog_content = "Atas nama Rear Admiral, aku mengangkat kalian berdua sebagai Sergeant!",
  ui_story_30420601_149_dialog_content = "Mulai hari ini, kalian akan dikenal sebagai Sergeant Hvit dan Sergeant Ulv dari Grand Navy Illumina! Paham?",
  ui_story_30420601_150_dialog_content = "Guk!",
  ui_story_30420601_151_dialog_content = "Jawab dengan \"Ya, Commander\", Sergeant!",
  ui_story_30420601_152_dialog_content = "Guk! Auuuh!",
  ui_story_30420601_153_dialog_content = "Bagus! Pelatihan kalian akan makin sulit mulai saat ini, jadi bersiaplah!",
  ui_story_30420601_154_dialog_content = "Guk...?",
  ui_story_30420601_155_dialog_content = "Untuk latihan hari ini, kita akan mulai dengan... Berenang 100 meter di laut!",
  ui_story_30420601_156_dialog_content = "Guk-guk!",
  ui_story_30420601_157_dialog_content = "H-hah? Kenapa kalian berdua tampak begitu bersemangat...?",
  ui_story_30420601_158_dialog_content = "Ehem... Kurasa itu wajar. Sebagai anggota angkatan laut yang bangga, melihat laut saja membuat kita semua bersemangat...",
  ui_story_30420601_159_dialog_content = "Sekarang... Mulai!",
  ui_story_30420601_160_dialog_content = "Guk!",
  ui_story_30420601_161_dialog_content = "H-hei! Tunggu aku!",
  ui_story_30420601_162_dialog_content = "Waaah! Ombaknya terlalu besar! Tolong! Selamatkan aku!",
  ui_story_30420601_163_dialog_content = "Grr....",
  ui_story_30420601_164_dialog_content = "Selamatkan... Aku...",
  ui_story_30420601_165_dialog_content = "Barton! Akhirnya kamu bangun!",
  ui_story_30420601_166_dialog_content = "...PlayerName? Sedang apa kamu di sini?",
  ui_story_30420601_167_option_content = "Aku datang untuk menyelamatkanmu",
  ui_story_30420601_168_option_content = "Aku hanya lewat",
  ui_story_30420601_169_dialog_content = "Kamu kesulitan di dalam air, jadi para serigala dan aku kemari untuk menarikmu keluar.",
  ui_story_30420601_170_dialog_content = "Guk!",
  ui_story_30420601_171_dialog_content = "Apakah aku... masih ada di pulau terpencil itu?",
  ui_story_30420601_172_dialog_content = "Pulau terpencil? Kamu memimpikan itu?",
  ui_story_30420601_173_dialog_content = "Sepertinya kamu tidak ingat... Kamu baru saja menyeretku ke laut!",
  ui_story_30420601_174_dialog_content = "Kamu mengatakan sesuatu tentang menguji peralatan terbaru angkatan laut...",
  ui_story_30420601_175_dialog_content = "Namun, kamu tersapu ombak sebelum kita bisa menguji apa pun...",
  ui_story_30420601_176_dialog_content = "Jadi, aku sudah tidak di pulau itu lagi... Syukurlah...",
  ui_story_30420601_177_dialog_content = "Namun, tetap saja, aku tidak pernah berharap untuk mengetahui Commander angkatan laut Illumina tidak bisa berenang.",
  ui_story_30420601_178_dialog_content = "Ehem... Aku hanya belum mulai belajar saja.",
  ui_story_30420601_179_dialog_content = "Benarkah...?",
  ui_story_30420601_180_dialog_content = "Sepertinya itu tidak tercatat di Conquest of the Sea karyamu...",
  ui_story_30420601_181_dialog_content = "Bagaimana kamu bisa mendapatkan catatan perjalananku?!",
  ui_story_30420601_182_dialog_content = "Vice memberikannya kepadaku... Dia bilang, ini buku wajib baca dari koleksi Most Popular Book di Illumina.",
  ui_story_30420601_183_dialog_content = "Harus kubilang, itu adalah buku yang sangat menginspirasi! Maukah kamu menandatangani bukuku?",
  ui_story_30420601_184_dialog_content = "Tanda tangan itu bukan masalah selama kamu memahami semangat di balik tulisan itu...",
  ui_story_30420601_185_dialog_content = "Tentu saja! Hasrat untuk tidak pernah menyerah atau menerima kekalahan dan tekad untuk mempertahankan impianmu dan terus maju! Benar?",
  ui_story_30420601_186_dialog_content = "...Ya.",
  ui_story_30420601_187_dialog_content = "Itu sebabnya aku telah mengambil keputusan!",
  ui_story_30420601_188_dialog_content = "Hahaha! Keputusan apa itu? Jika kamu berniat untuk bergabung dengan angkatan laut Illumina yang berjaya, kami menyambutmu dengan tangan terbuka!",
  ui_story_30420601_189_dialog_content = "Tidak! Aku telah memutuskan bahwa hari ini... Aku akan mengajarimu cara berenang!",
  ui_story_30420601_190_dialog_content = "B-berenang...?",
  ui_story_30420601_191_dialog_content = "Barton? Hei, Barton!",
  ui_story_30420601_192_dialog_content = "Dia pingsan lagi..."
}
return config
